// Typed access + search over the offline `baml describe` snapshot
// (`stdlib.json`, generated by scripts/gen-baml-docs). This is the real stdlib
// surface (259 symbols across 26 namespaces), used by the bamlcode `baml
// describe` side panel for instant, no-runtime symbol lookup.
import raw from './stdlib.json';

export type DocKind = 'function' | 'class' | 'enum' | 'interface' | 'type';

export interface DocMethod {
  name: string;
  signature: string;
  docstring: string | null;
  kind: 'instance' | 'static';
}

export interface DocSymbol {
  name: string;
  kind: DocKind;
  file: string;
  line: number;
  shape: string | null;
  docstring: string | null;
  resolved_type: string | null;
  dependencies: string[];
  methods?: DocMethod[];
}

export const SYMBOLS = raw as unknown as DocSymbol[];

const BY_NAME = new Map<string, DocSymbol>(SYMBOLS.map((s) => [s.name, s]));

/** Last dotted segment, e.g. `stringify` from `baml.json.stringify`. */
function leaf(name: string): string {
  const i = name.lastIndexOf('.');
  return i < 0 ? name : name.slice(i + 1);
}

/** Internal/shim symbols (`_foo`, `__bar`) are hidden from browse + fuzzy
 *  search, but still resolvable by an exact query. */
function isInternal(name: string): boolean {
  return leaf(name).startsWith('_');
}

export function getSymbol(name: string): DocSymbol | undefined {
  return BY_NAME.get(name);
}

export interface SearchHit {
  /** The owning top-level symbol to render. */
  symbol: DocSymbol;
  /** Set when the query matched a method rather than the symbol itself. */
  method?: DocMethod;
  score: number;
}

/**
 * Rank symbols (and their methods) against a free-text query. Matches the full
 * dotted name, its leaf, and method names; exact/prefix hits rank first.
 */
export function searchSymbols(query: string, limit = 30): SearchHit[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const hits: SearchHit[] = [];

  const scoreName = (full: string): number => {
    const f = full.toLowerCase();
    const l = leaf(full).toLowerCase();
    if (f === q || l === q) return 100;
    if (l.startsWith(q)) return 80;
    if (f.startsWith(q)) return 70;
    if (l.includes(q)) return 50;
    if (f.includes(q)) return 40;
    return 0;
  };

  for (const s of SYMBOLS) {
    const internal = isInternal(s.name);
    let best = scoreName(s.name);
    let bestMethod: DocMethod | undefined;
    for (const m of s.methods ?? []) {
      const ms = scoreName(`${s.name}.${m.name}`);
      // Also score the bare method leaf (e.g. `chars`) a touch higher so
      // `chars` surfaces `String.chars` even though the class is `String`.
      const direct =
        m.name.toLowerCase() === q
          ? 100
          : m.name.toLowerCase().startsWith(q)
            ? 80
            : 0;
      const score = Math.max(ms, direct);
      if (score > best) {
        best = score;
        bestMethod = m;
      }
    }
    if (best <= 0) continue;
    // Exact query on an internal symbol still shows; otherwise hide internals.
    if (internal && best < 100) continue;
    // Shorter, shallower names win ties (prefer `baml.String` over deep paths).
    const tie = -s.name.length / 1000 - s.name.split('.').length / 100;
    hits.push({ method: bestMethod, score: best + tie, symbol: s });
  }

  hits.sort((a, b) => b.score - a.score);
  return hits.slice(0, limit);
}
